    'rejected_qc': r'rejeitadas por $q_C$',
    'rejected_both': 'rejeitadas por ambos',
}

summary = pd.DataFrame({
    "Método": METHOD_ORDER,
    "Conjunto": ["determinístico", "determinístico", "seed 6", "seed 9"],
